function isSenderFingerprint(req,senderData){try{if(!senderData)return false;const ip=getClientIP(req);const ua=String(req.headers['user-agent']||'');if(senderData.lastIP&&ip===senderData.lastIP)return true;if(senderData.lastIP&&senderData.lastUserAgent&&ip===senderData.lastIP&&ua===senderData.lastUserAgent)return true;const fp=fpHash(ip,ua);const senderFps=Array.isArray(senderData.senderFingerprints)?senderData.senderFingerprints:[];if(senderFps.indexOf(fp)!==-1)return true;return false;}catch(e){return false;}}
