function htmlToPlainText(html){if(!html)return '';let t=String(html);try{t=t.replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ');t=t.replace(/<br\s*\/?>/gi,'\n').replace(/<\/(p|div|tr|li|h[1-6])>/gi,'\n');t=t.replace(/<li[^>]*>/gi,'- ');t=t.replace(/<a\s[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,function(m,url,txt){const label=String(txt).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();if(!label||label===url)return url;return label+' ('+url+')';});t=t.replace(/<img[^>]*alt\s*=\s*["']([^"']*)["'][^>]*>/gi,'$1\n');t=t.replace(/<img[^>]*>/gi,'');t=t.replace(/<[^>]+>/g,' ');t=t.replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&mdash;/g,'-').replace(/&ndash;/g,'-');t=t.replace(/[^\S\n]+/g,' ').replace(/ *\n */g,'\n').replace(/\n{3,}/g,'\n\n');t=t.replace(/ +([,.!?;:])/g,'$1');t=t.trim();return t;}catch(e){return String(html).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}}
function buildPlainTextFooter(u){try{const nm=(u&&u.name)?String(u.name):'';const em=(u&&u.email)?String(u.email):'';let f='--'+(nm?'\n'+nm:'');if(em)f+='\n'+em;f+='\n\nYou received this email from '+(nm||'our team')+'.';f+='\nPrivacy Policy: '+BACKEND_URL+'/privacy';f+='\nUnsubscribe: reply to this email with the subject "unsubscribe".';return f;}catch(e){return '';}}
function analyzeDeliverability(subject,html,text){const issues=[];let score=100;try{const s=(subject||'').toLowerCase();const h=(html||'').toLowerCase();const plain=(text||'').toLowerCase();const HAM=['act now','buy now','limited time','click here','cash','prize','winner','guarantee','risk-free','no cost','make money','work from home','earn money','urgent','100% free','apply now','lowest price','credit card','viagra','casino','lottery','double your'];const found=HAM.filter(function(w){return s.indexOf(w)!==-1||plain.indexOf(w)!==-1;});if(found.length){issues.push({severity:'high',message:'Spam trigger words: '+found.slice(0,4).join(', ')});score-=found.length*12;}if(/!{3,}/.test(subject||'')){issues.push({severity:'medium',message:'Subject has 3+ exclamation marks'});score-=8;}if(subject&&subject===subject.toUpperCase()&&subject.length>8){issues.push({severity:'high',message:'Subject is all CAPS'});score-=20;}if(!text||text.replace(/\s/g,'').length<40){issues.push({severity:'high',message:'Plain-text version missing or too short'});score-=15;}const imgCount=(h.match(/<img/g)||[]).length;if(imgCount>0&&imgCount>6){issues.push({severity:'medium',message:'Too many images ('+imgCount+')'});score-=6;}if(/<img(?![^>]*\balt=)/.test(h)){issues.push({severity:'low',message:'Some images missing alt text'});score-=4;}const shorteners=/(bit\.ly|tinyurl|t\.co|goo\.gl|is\.gd|ow\.ly|shorturl|rebrand\.ly|cutt\.ly)/i;if(shorteners.test(h)){issues.push({severity:'high',message:'URL shortener detected (spam signal)'});score-=18;}const linkCount=(h.match(/href\s*=\s*["']https?:/g)||[]).length;if(linkCount>10){issues.push({severity:'medium',message:'Too many links ('+linkCount+')'});score-=8;}if(/<script|<iframe|onclick\s*=/i.test(h)){issues.push({severity:'high',message:'Script/iframe/onclick detected'});score-=25;}if(h.indexOf('<html')===-1&&h.indexOf('<body')===-1){issues.push({severity:'low',message:'Missing proper HTML structure'});score-=5;}if(score<0)score=0;return{score,issues,label:score>=85?'EXCELLENT':score>=70?'GOOD':score>=50?'RISKY':'POOR'};}catch(e){return{score:70,issues:[],label:'UNKNOWN'};}}
function sanitizeSubject(subject){if(!subject)return '';let s=String(subject).replace(/!{2,}/g,'!').replace(/\?{2,}/g,'?').trim();if(s.length>78)s=s.substring(0,75)+'...';return s;}
function makeUniqueSubject(subj){try{let clean=String(subj||'').replace(/[\u200B\u200C\u200D\uFEFF\u2060]/g,'');clean=sanitizeSubject(clean);if(!clean)return clean;const count=1+Math.floor(Math.random()*3);const zw='\u200B'.repeat(count);return clean+zw;}catch(e){return sanitizeSubject(subj);}}
function wrapHtmlDocument(innerHtml,subject,userEmail){try{const title=String(subject||'Message').replace(/[<>]/g,'').substring(0,120);return '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">'+'<html xmlns="http://www.w3.org/1999/xhtml" lang="en">'+'<head>'+'<meta charset="utf-8">'+'<meta http-equiv="Content-Type" content="text/html; charset=utf-8">'+'<meta name="viewport" content="width=device-width,initial-scale=1">'+'<meta name="x-apple-disable-message-reformatting">'+'<title>'+title+'</title>'+'<style type="text/css">'+'body{margin:0;padding:0;background:#ffffff;}'+'table{border-collapse:collapse;mso-table-lspace:0;mso-table-rspace:0;}'+'img{border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic;}'+'a{color:#1a73e8;}'+'</style>'+'</head>'+'<body style="margin:0;padding:0;background:#ffffff;">'+innerHtml+'</body></html>';}catch(e){return '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>'+innerHtml+'</body></html>';}}
function getClientIP(req){const fwd=req.headers['x-forwarded-for'];if(fwd)return String(fwd).split(',')[0].trim();return req.headers['x-real-ip']||(req.connection&&req.connection.remoteAddress)||(req.socket&&req.socket.remoteAddress)||'unknown';}
function localAnalysis(subject,body){const SW=['free','guarantee','act now','click here','limited time','buy now','cash','prize','urgent','risk-free','earn money','work from home','make money','no cost','no fees'];const text=((subject||'')+' '+(body||'')).toLowerCase();const found=SW.filter(w=>text.includes(w));const links=(body.match(/https?:\/\//g)||[]).length;const exc=((subject.match(/!/g)||[]).length)>1;const caps=subject===subject.toUpperCase()&&subject.length>5;const cb=(body||'').replace(/<[^>]+>/g,' ').trim();const wc=cb.split(/\s+/).filter(w=>w).length;const issues=[];if(found.length)issues.push({severity:'high',message:'Contains: '+found.slice(0,3).join(', ')});if(links>2)issues.push({severity:'medium',message:links+' links found'});if(exc)issues.push({severity:'low',message:'Multiple exclamation marks'});if(caps)issues.push({severity:'high',message:'Subject in ALL CAPS'});if(wc<20&&wc>0)issues.push({severity:'medium',message:'Body too short'});const score=Math.min(100,found.length*20+(links>2?15:0)+(exc?10:0)+(caps?25:0)+(wc<20&&wc>0?15:0));return{score,prediction:score<=15?'EXCELLENT':score<=40?'GOOD':score<=70?'RISKY':'SPAM',inboxProbability:100-score,issues,suggestions:[],tone:'professional',readability:75,emotionalTone:'neutral'};}
