app.post('/api/ocr/extract',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{const uid=req.session.user.id;let fileName='';try{const{base64,mimeType,filename,emailsOnly}=req.body||{};fileName=filename||'';if(!base64||base64.length<50){await logOcrUsage(uid,false,0,'No image data provided',fileName,false,'');return res.json({ok:false,error:'No image data provided'});}let buf;try{buf=Buffer.from(base64,'base64');}catch(e){await logOcrUsage(uid,false,0,'Invalid base64',fileName,false,'');return res.json({ok:false,error:'Invalid image data.'});}if(buf.length>MAX_OCR_IMAGE_SIZE){const kb=Math.round(buf.length/1024);await logOcrUsage(uid,false,0,'Image too large: '+kb+'KB',fileName,false,'');return res.json({ok:false,error:'Image too large ('+kb+' KB). Max '+Math.round(MAX_OCR_IMAGE_SIZE/1024)+' KB.'});}const mime=(mimeType||'image/jpeg').toLowerCase();const allowed=['image/jpeg','image/png','image/webp','image/gif','image/bmp','image/tiff'];const safeMime=allowed.indexOf(mime)!==-1?mime:'image/jpeg';const params=new URLSearchParams();params.append('base64Image','data:'+safeMime+';base64,'+base64);params.append('language','eng');params.append('isOverlayRequired','false');params.append('OCREngine','2');params.append('scale','true');params.append('isTable','false');params.append('detectOrientation','true');let ocrRes;try{ocrRes=await fetchWithTimeout('https://api.ocr.space/parse/image',{method:'POST',headers:{'apikey':OCR_SPACE_API_KEY,'Content-Type':'application/x-www-form-urlencoded'},body:params.toString()},60000);}catch(netErr){await logOcrUsage(uid,false,0,'Network: '+netErr.message,fileName,false,'');return res.json({ok:false,error:'OCR service unreachable.'});}if(!ocrRes.ok){await logOcrUsage(uid,false,0,'OCR HTTP '+ocrRes.status,fileName,false,'');return res.json({ok:false,error:'OCR service error (HTTP '+ocrRes.status+').'});}let ocrData;try{ocrData=await ocrRes.json();}catch(e){await logOcrUsage(uid,false,0,'Invalid OCR response',fileName,false,'');return res.json({ok:false,error:'Invalid response from OCR service.'});}if(ocrData.IsErroredOnProcessing){const errMsg=(ocrData.ErrorMessage&&Array.isArray(ocrData.ErrorMessage))?ocrData.ErrorMessage.join(' '):(ocrData.ErrorMessage||'OCR failed');await logOcrUsage(uid,false,0,errMsg,fileName,false,'');const low=String(errMsg).toLowerCase();if(low.indexOf('limit')!==-1||low.indexOf('quota')!==-1)return res.json({ok:false,error:'OCR monthly limit reached.'});return res.json({ok:false,error:errMsg});}if(!ocrData.ParsedResults||!ocrData.ParsedResults.length){await logOcrUsage(uid,false,0,'No text detected',fileName,false,'');return res.json({ok:false,error:'No text detected.'});}const text=ocrData.ParsedResults.map(r=>r.ParsedText||'').join('\n').trim();if(!text||text.length<2){await logOcrUsage(uid,false,0,'No readable text',fileName,false,'');return res.json({ok:false,error:'No readable text found.'});}const emailsFound=extractEmailsOnly(text);const wantEmailsOnly=emailsOnly===true;if(wantEmailsOnly&&emailsFound.length===0){await logOcrUsage(uid,true,0,'',fileName,false,'');return res.json({ok:true,text:'',chars:0,emails:[],emailCount:0,emailsOnly:true,noEmailFound:true,error:'No email found in screenshot.'});}await logOcrUsage(uid,true,text.length,'',fileName,false,'');res.json({ok:true,text:text.substring(0,30000),chars:text.length,emails:emailsFound,emailCount:emailsFound.length,emailsOnly:wantEmailsOnly===true});}catch(e){console.error('OCR error:',e.message);await logOcrUsage(uid,false,0,'Server: '+e.message,fileName,false,'');res.json({ok:false,error:'OCR failed: '+e.message});}});
