app.post('/api/bulk/parse-file',authRequired,rateLimit(60*1000,30,null),async(req,res)=>{try{const{base64,filename,mimeType}=req.body||{};if(!base64||!filename)return res.json({ok:false,error:'Missing file data'});let buf;try{buf=Buffer.from(base64,'base64');}catch(e){return res.json({ok:false,error:'Invalid file data'});}if(buf.length>MAX_BULK_FILE_SIZE)return res.json({ok:false,error:'File too large (max 5MB)'});const name=String(filename).toLowerCase();const mime=String(mimeType||'').toLowerCase();let text='';try{if(name.endsWith('.csv')||name.endsWith('.txt')||name.endsWith('.tsv')||mime.indexOf('text/')===0){text=buf.toString('utf8').replace(/^\uFEFF/,'').replace(/\u0000/g,'');}else if(name.endsWith('.xlsx')||name.endsWith('.xls')){try{const XLSX=require('xlsx');const wb=XLSX.read(buf,{type:'buffer'});const parts=[];for(const sn of wb.SheetNames){const sheet=wb.Sheets[sn];const csv=XLSX.utils.sheet_to_csv(sheet);parts.push(csv);}text=parts.join('\n');}catch(xe){return res.json({ok:false,error:'Excel file not supported on server. Please save as CSV and try again.'});}}else{text=await extractCvFromBuffer(buf,filename,mimeType);}}catch(e){return res.json({ok:false,error:'Could not read file: '+e.message});}if(!text||text.replace(/\s/g,'').length<3)return res.json({ok:false,error:'No readable content found in file'});const parsed=parseBulkTextToRecipients(text);if(!parsed.recipients.length)return res.json({ok:false,error:'No valid emails found in file',text:''});res.json({ok:true,recipients:parsed.recipients,total:parsed.recipients.length,duplicatesSkipped:parsed.duplicates,filename:filename,previewText:text.substring(0,500)});}catch(e){res.json({ok:false,error:'Parse failed: '+e.message});}});
