app.post('/api/smtp/connect',authRequired,rateLimit(60*1000,10,null),async(req,res)=>{try{const{appPassword,alsoEnableImap}=req.body||{};if(!appPassword||appPassword.replace(/\s/g,'').length<16)return res.json({ok:false,error:'App password must be 16 characters.'});const cleanPass=appPassword.replace(/\s/g,'');const userEmail=req.session.user.email;const transporter=createTransporter(userEmail,cleanPass);try{await transporter.verify();}catch(err){return res.json({ok:false,error:'Connection failed: '+err.message});}const update={smtpAppPassword:encrypt(cleanPass),smtpEnabled:true,smtpConnectedAt:new Date()};if(alsoEnableImap){const test=await testImapConnection(userEmail,cleanPass);if(test.ok){update.imapAppPassword=encrypt(cleanPass);update.imapEnabled=true;update.imapConnectedAt=new Date();}}await db.collection('users').doc(req.session.user.id).update(update);cacheDel('quota:'+req.session.user.id);cacheDel('status:'+req.session.user.id);res.json({ok:true,message:'Gmail connected successfully',imapEnabled:!!update.imapEnabled});}catch(e){res.json({ok:false,error:'Connection failed: '+e.message});}});
