app.post('/api/imap/inbox',authRequired,async(req,res)=>{try{const uid=req.session.user.id;const u=await getUserData(uid);if(!u.imapEnabled||!u.imapAppPassword)return res.json({ok:false,error:'Inbox not connected'});const folder=req.body.folder||'INBOX';const page=parseInt(req.body.page)||1;const pageSize=Math.min(parseInt(req.body.pageSize)||20,50);const skipCache=req.body.skipCache===true;const ck='imapInbox:'+uid+':'+folder+':'+page+':'+pageSize;if(!skipCache){const cached=cacheGet(ck);if(cached){res.set('X-Cache','HIT');return res.json(cached);}}const result=await fetchImapEmails(u.email,u.imapAppPassword,{folder,page,pageSize});if(!result.ok)return res.json({ok:false,error:result.error});const coll=db.collection('users').doc(uid).collection('imapEmails');const writes=[];for(const e of result.emails){const key=folder.replace(/[^A-Za-z0-9]/g,'_')+'_'+e.uid;writes.push(coll.doc(key).set(e,{merge:true}).catch(function(){}));if(e.from)updateSenderMemory(uid,{from:e.from,fromName:e.fromName,subject:e.subject,textBody:''});}Promise.all(writes).catch(function(){});db.collection('users').doc(uid).update({imapLastSync:new Date()}).catch(function(){});const out={ok:true,emails:result.emails,total:result.total,hasMore:result.hasMore,page:result.page,pageSize:result.pageSize,folder:folder,userEmail:u.email};cacheSet(ck,out,CACHE_TTL.imapInbox);res.set('X-Cache','MISS');res.json(out);}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/imap/body',authRequired,async(req,res)=>{try{const u=await getUserData(req.session.user.id);if(!u.imapEnabled||!u.imapAppPassword)return res.json({ok:false,error:'Inbox not connected'});const{folder,uid}=req.body;if(!uid)return res.json({ok:false,error:'Missing uid'});const folderKey=(folder||'INBOX').replace(/[^A-Za-z0-9]/g,'_');const docId=folderKey+'_'+uid;const ref=db.collection('users').doc(req.session.user.id).collection('imapEmails').doc(docId);const cached=await ref.get();if(cached.exists&&cached.data().bodyFetched){const cd=cached.data();return res.json({ok:true,email:Object.assign({id:docId,userEmail:u.email},cd)});}const result=await fetchImapBody(u.email,u.imapAppPassword,folder||'INBOX',uid);if(!result.ok)return res.json({ok:false,error:result.error});await ref.set(Object.assign({},result.body,{bodyFetched:true,isRead:true}),{merge:true});const fresh=await ref.get();res.json({ok:true,email:Object.assign({id:docId,userEmail:u.email},fresh.data())});}catch(e){res.json({ok:false,error:e.message});}});
