app.post('/api/inbox/reply',authRequired,rateLimit(60*1000,30,null),async(req,res)=>{try{const{to,subject,body,inReplyTo,references,includeSignature,includeLogo,includeAttachments,selectedFileIds}=req.body;if(!to||!subject||!body)return res.json({ok:false,error:'Missing fields'});const uid=req.session.user.id;const u=await getUserData(uid);if(!u.smtpEnabled||!u.smtpAppPassword)return res.json({ok:false,error:'Connect Gmail first'});const userEmailLower=String(req.session.user.email||'').toLowerCase();const toLower=String(to).toLowerCase().trim();if(toLower===userEmailLower)return res.json({ok:false,error:'Cannot reply to your own email address.'});const transporter=createTransporter(req.session.user.email,u.smtpAppPassword);let sigHtml='';const hasSignature=!!(u.signature&&u.signature.trim().length>20);if(hasSignature&&includeSignature!==false){let sig=u.signature;if(includeLogo===false)sig=sig.replace(/<td[^>]*>\s*<img[\s\S]*?<\/td>/gi,'').replace(/<img[^>]*>/gi,'').replace(/<td[^>]*>\s*<\/td>/gi,'');else sig=replaceInlineLogoWithPublicUrl(sig,uid);sigHtml='<div style="margin-top:16px;padding-top:12px;border-top:1px solid #e5e7eb;">'+sig+'</div>';}const atts=[];const attNames=[];if(includeAttachments===true&&Array.isArray(selectedFileIds)&&selectedFileIds.length>0){for(const fid of selectedFileIds){try{const fd=await db.collection('users').doc(uid).collection('files').doc(fid).get();if(fd.exists){const f=fd.data();if(f.base64){atts.push({filename:f.name,content:Buffer.from(f.base64,'base64'),contentType:f.mimeType||'application/octet-stream'});attNames.push(f.name);}}}catch(fe){}}}const bodyHtml=body.replace(/\n/g,'<br>');const fullHtml=wrapHtmlDocument('<div style="font-family:Arial,sans-serif;font-size:14px;color:#333;line-height:1.6;max-width:640px;">'+bodyHtml+sigHtml+'</div>',subject,req.session.user.email);const sendTrackToken=crypto.randomBytes(16).toString('hex');const normalizedInReplyTo=normalizeMessageId(inReplyTo);let normalizedRefs='';if(references)normalizedRefs=normalizeReferences(references);let finalInReplyTo=normalizedInReplyTo;if(!finalInReplyTo&&normalizedRefs){const refList=normalizedRefs.split(/\s+/).filter(Boolean);if(refList.length>0)finalInReplyTo=refList[refList.length-1];}let finalRefs=normalizedRefs;if(finalInReplyTo){if(!finalRefs)finalRefs=finalInReplyTo;else if(finalRefs.indexOf(finalInReplyTo)===-1)finalRefs=finalRefs+' '+finalInReplyTo;}let cleanSubject=sanitizeSubject(subject);if(!/^re:\s/i.test(cleanSubject))cleanSubject='Re: '+cleanSubject.replace(/^re:\s*/i,'');const logRef=await db.collection('users').doc(uid).collection('emailLog').add({recipientId:null,recipientEmail:to,company:'',subject:cleanSubject,sentAt:new Date(),attachmentsCount:atts.length,attachmentNames:attNames,aiPrediction:'GOOD',aiScore:20,aiInboxProb:80,sendTrackToken,openedAt:null,hasSignature:hasSignature,templateName:'',isReply:true,inReplyTo:finalInReplyTo,references:finalRefs});const logId=logRef.id;const trackUrl=BACKEND_URL+'/track/'+logId+'?u='+uid+'&t='+sendTrackToken;const pix='<img src="'+trackUrl+'" width="1" height="1" alt="" style="border:0;display:block;width:1px;height:1px">';const withClickLinks=rewriteLinksForTracking(fullHtml,logId,uid,sendTrackToken);const finalHtml=withClickLinks+pix;const uniqueEntityId=crypto.randomBytes(12).toString('hex');const messageId='<'+uniqueEntityId+'.'+Date.now()+'@mailflowpro.dpdns.org>';const headers={'X-Entity-Ref-ID':uniqueEntityId,'Message-ID':messageId,'X-Mailer':'MailFlow Pro v'+APP_VERSION};if(finalInReplyTo)headers['In-Reply-To']=finalInReplyTo;if(finalRefs)headers['References']=finalRefs;const mailOptions={from:'"'+(u.name||'User')+'" <'+req.session.user.email+'>',to:to,subject:cleanSubject,text:htmlToPlainText(fullHtml),html:finalHtml,headers:headers,messageId:messageId};if(finalInReplyTo)mailOptions.inReplyTo=finalInReplyTo;if(finalRefs)mailOptions.references=finalRefs;if(atts.length>0)mailOptions.attachments=atts;const info=await transporter.sendMail(mailOptions);cacheDel('quota:'+uid);cacheDel('stats:'+uid);cacheDel('myEmails:'+uid);await db.collection('users').doc(uid).collection('replyLog').add({to,subject:cleanSubject,body,sentAt:new Date(),messageId:info.messageId||'',inReplyTo:finalInReplyTo,references:finalRefs,logId:logId,attachmentNames:attNames});if(u.imapEnabled&&u.imapAppPassword){const cleanHeaders={'X-Entity-Ref-ID':uniqueEntityId,'Message-ID':messageId,'X-Mailer':'MailFlow Pro v'+APP_VERSION};if(finalInReplyTo)cleanHeaders['In-Reply-To']=finalInReplyTo;if(finalRefs)cleanHeaders['References']=finalRefs;const cleanReplyMail={from:'"'+(u.name||'User')+'" <'+req.session.user.email+'>',to:to,subject:cleanSubject,text:htmlToPlainText(fullHtml),html:fullHtml,headers:cleanHeaders,messageId:messageId};if(finalInReplyTo)cleanReplyMail.inReplyTo=finalInReplyTo;if(finalRefs)cleanReplyMail.references=finalRefs;if(atts.length>0)cleanReplyMail.attachments=atts;stripPixelFromSentFolder(req.session.user.email,u.imapAppPassword,uniqueEntityId,cleanReplyMail,logId,uid).catch(function(){});}res.json({ok:true,id:info.messageId,logId:logId,hasSignature:hasSignature,attachmentsCount:atts.length,threadedAs:finalInReplyTo?'reply':'new',inReplyTo:finalInReplyTo,references:finalRefs});}catch(e){res.json({ok:false,error:e.message});}});
