app.post('/api/ai/analyze-live',authRequired,rateLimit(60*1000,60,null),async(req,res)=>{try{const{subject,body}=req.body;if(!subject&&!body)return res.json({ok:true,empty:true});try{const cleanBody=(body||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().substring(0,1200);const prompt='Analyze this email for spam score. Return ONLY JSON.\nSubject: "'+(subject||'').substring(0,200)+'"\nBody: "'+cleanBody+'"\nReturn: {"score":0-100,"prediction":"EXCELLENT"|"GOOD"|"RISKY"|"SPAM","inboxProbability":0-100,"issues":[{"severity":"low"|"medium"|"high","message":"string"}],"suggestions":["string"],"tone":"string"}';const text=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(text);if(parsed&&typeof parsed.score==='number')return res.json(Object.assign({ok:true,aiPowered:true},parsed));}catch(aiErr){}res.json(Object.assign({ok:true,aiPowered:false},localAnalysis(subject,body)));}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/ai/smart-reply',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{try{const{originalSubject,originalBody,originalFrom,instruction}=req.body;if(!originalBody)return res.json({ok:false,error:'No original body'});const u=await getUserData(req.session.user.id);const aiProfile=u.aiProfile||{};const userName=aiProfile.fullName||u.name||u.email.split('@')[0];const userCompany=aiProfile.company||(u.sigFields&&u.sigFields.company)||'';const userPos=aiProfile.designation||(u.sigFields&&u.sigFields.pos)||'';const userTone=aiProfile.tone||'professional';const userAbout=aiProfile.aboutMe||'';const userIndustry=aiProfile.industry||'';const hasSignature=!!(u.signature&&u.signature.trim().length>20);const sigInstruction=hasSignature?'A professional HTML signature will be auto-appended. Do NOT include any sign-off, name, contact info, or closing line.':'End with clean professional sign-off. Include name "'+userName+'"'+(userPos?', '+userPos:'')+(userCompany?' at '+userCompany:'')+'.';const prompt='You are an expert business email assistant writing a reply on behalf of '+userName+'.\n\nWRITER IDENTITY:\n- Name: '+userName+'\n'+(userPos?'- Position: '+userPos+'\n':'')+(userCompany?'- Company: '+userCompany+'\n':'')+(userIndustry?'- Industry: '+userIndustry+'\n':'')+(userAbout?'- About: '+userAbout+'\n':'')+'- Preferred Tone: '+userTone+'\n\nINCOMING EMAIL:\nFrom: '+(originalFrom||'Unknown')+'\nSubject: '+(originalSubject||'(no subject)')+'\nBody:\n"""\n'+(originalBody||'').substring(0,4000)+'\n"""\n\n'+(instruction?'EXTRA INSTRUCTION: '+instruction:'')+'\n\nTASK: Write a thoughtful, professional reply.\n\nCRITICAL RULES:\n1. Reply in professional ENGLISH only.\n2. Write in FIRST PERSON as '+userName+'.\n3. Match tone: '+userTone+'.\n4. Address EVERY point.\n5. Keep 2-4 paragraphs.\n6. '+sigInstruction+'\n7. Do NOT invent facts.\n\nReturn ONLY valid JSON:\n{"subject":"Re: (matching original subject)","body":"complete reply text with \\n\\n for paragraphs"}';try{const text=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(text);if(parsed&&parsed.body&&parsed.body.length>20){const cleanedBody=hasSignature?stripSignature(parsed.body):parsed.body;return res.json({ok:true,subject:parsed.subject||('Re: '+originalSubject),body:cleanedBody,aiPowered:true,hasUserSignature:hasSignature});}}catch(e){}res.json({ok:true,subject:'Re: '+(originalSubject||''),body:'Hi,\n\nThank you for reaching out. I will get back to you shortly.',aiPowered:false,hasUserSignature:hasSignature});}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/ai/write-email',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{try{const{context,recipientName,recipientCompany,tone,length}=req.body;if(!context)return res.json({ok:false,error:'Please describe the email purpose'});const u=await getUserData(req.session.user.id);const aiProfile=u.aiProfile||{};const writerName=aiProfile.fullName||u.name||'the sender';const writerDesig=aiProfile.designation||'';const writerCompany=aiProfile.company||'';const writerAbout=aiProfile.aboutMe||'';const writerIndustry=aiProfile.industry||'';const TM={formal:'professional and business-appropriate',friendly:'warm and approachable yet polished',casual:'relaxed but professional',persuasive:'confident and compelling'};const LM={short:'80-100 words, concise',medium:'130-180 words, balanced',long:'200-280 words, detailed'};const prompt='Write a high-quality professional email.\n\nWRITER: '+writerName+(writerDesig?', '+writerDesig:'')+(writerCompany?' at '+writerCompany:'')+'\n'+(writerIndustry?'Industry: '+writerIndustry+'\n':'')+(writerAbout?'About writer: '+writerAbout+'\n':'')+'\nPURPOSE: '+context+'\nRECIPIENT: '+(recipientName||'unknown')+'\nRECIPIENT COMPANY: '+(recipientCompany||'unknown')+'\nTONE: '+(TM[tone]||TM.formal)+'\nLENGTH: '+(LM[length]||LM.medium)+'\n\nRULES:\n- Output in professional English only\n- No sign-off, no name, no signature\n- Clear, actionable, human\n\nReturn ONLY valid JSON:\n{"subject":"under 65 chars","body":"email body with \\n\\n for paragraphs"}';try{const text=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(text);if(parsed&&parsed.subject&&parsed.body)return res.json({ok:true,subject:parsed.subject,body:stripSignature(parsed.body),aiPowered:true});}catch(e){}res.json({ok:true,subject:context.substring(0,60),body:'Dear '+(recipientName||'there')+',\n\nI hope this message finds you well.\n\n'+context,aiPowered:false});}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/ai/extract-cv',authRequired,rateLimit(60*1000,15,null),async(req,res)=>{try{const{fileId,base64,mimeType,filename}=req.body||{};let buf=null,fname=filename||'cv',mime=mimeType||'';if(fileId){const f=await db.collection('users').doc(req.session.user.id).collection('files').doc(fileId).get();if(!f.exists)return res.json({ok:false,error:'File not found.'});const meta=f.data();if(!meta.base64||meta.base64.length<50)return res.json({ok:false,error:'This file has no data.'});fname=meta.name||fname;mime=meta.mimeType||mime;try{buf=Buffer.from(meta.base64,'base64');}catch(e){return res.json({ok:false,error:'File data is corrupted.'});}}else if(base64){try{buf=Buffer.from(base64,'base64');}catch(e){return res.json({ok:false,error:'Invalid file data'});}if(buf.length>MAX_FILE_SIZE)return res.json({ok:false,error:'Maximum file size is 3MB.'});}else return res.json({ok:false,error:'No file provided'});if(!buf||buf.length<20)return res.json({ok:false,error:'File is empty or corrupted.'});const text=await extractCvFromBuffer(buf,fname,mime);if(!text||text.replace(/\s/g,'').length<30||looksLikeBinaryCv(text))return res.json({ok:false,error:'Could not read text. Try pasting manually.'});res.json({ok:true,text:text.substring(0,20000),filename:fname,chars:text.length});}catch(e){res.json({ok:false,error:'File processing error: '+e.message});}});
app.post('/api/ai/analyze-cv',authRequired,rateLimit(60*1000,15,null),async(req,res)=>{try{const{cvText,targetRole,jobDescription,fileId}=req.body;let text=cvText||'';if(fileId&&(!text||looksLikeBinaryCv(text))){try{const f=await db.collection('users').doc(req.session.user.id).collection('files').doc(fileId).get();if(f.exists){const meta=f.data();if(meta.base64&&meta.base64.length>100){text=await extractCvFromBuffer(Buffer.from(meta.base64,'base64'),meta.name||'cv',meta.mimeType||'');}}}catch(e){}}if(looksLikeBinaryCv(text))return res.json({ok:false,error:'CV is not readable.'});if(!text||text.replace(/\s/g,'').length<30)return res.json({ok:false,error:'CV text is too short or empty.'});const u=await getUserData(req.session.user.id);const aiProfile=u.aiProfile||{};const writerName=aiProfile.fullName||u.name||'the applicant';const writerCompany=aiProfile.company||'';const prompt='Analyze this CV and write a job application email.\n\nRULES: Output in professional English. First person as '+writerName+'.'+(writerCompany?' Current company: '+writerCompany:'')+'\n\nCV:\n"""\n'+text.substring(0,3800)+'\n"""\n\nTARGET ROLE: '+(targetRole||'Not specified')+'\n'+(jobDescription?'JOB DESCRIPTION:\n'+jobDescription.substring(0,800):'')+'\n\nReturn ONLY JSON:\n{"subject":"under 65 chars","body":"email with \\n\\n","keySkills":["s1","s2","s3","s4","s5"],"analysis":"2-3 sentences","score":0-100}';const aiText=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(aiText);if(parsed&&parsed.subject&&parsed.body)return res.json({ok:true,subject:parsed.subject,body:stripSignature(parsed.body),keySkills:parsed.keySkills||[],analysis:parsed.analysis||'',score:parsed.score||70,aiPowered:true});res.json({ok:false,error:'AI could not parse the CV.'});}catch(e){res.json({ok:false,error:'Analysis failed: '+e.message});}});
app.post('/api/ai/generate-subjects',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{try{const{context}=req.body;const prompt='Generate 5 email subject lines. Return ONLY JSON.\nMax 60 chars each, no spam words.\nContext: '+(context||'professional outreach')+'\nReturn: {"subjects":["s1","s2","s3","s4","s5"]}';try{const text=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(text);if(parsed&&parsed.subjects&&parsed.subjects.length>=3)return res.json({ok:true,subjects:parsed.subjects,aiPowered:true});}catch(e){}const c=(context||'Professional Outreach').substring(0,50);res.json({ok:true,subjects:[c,'Quick question about '+c,'Following up on '+c],aiPowered:false});}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/ai/improve-email',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{try{const{subject,body,isReply}=req.body;const prompt='Improve this email.\n\nSubject: "'+(subject||'')+'"\nBody:\n"""\n'+(body||'').substring(0,1500)+'\n"""\n\nReturn ONLY JSON:\n{"improvedSubject":"...","improvedBody":"...","beforeScore":50,"afterScore":85}';try{const text=await callAI(prompt,req.session.user.id);const parsed=safeParseJSON(text);if(parsed&&parsed.improvedSubject)return res.json({ok:true,improvedSubject:parsed.improvedSubject,improvedBody:stripSignature(parsed.improvedBody||''),beforeScore:parsed.beforeScore||50,afterScore:parsed.afterScore||85,aiPowered:true});}catch(e){}res.json({ok:true,improvedSubject:subject,improvedBody:body,beforeScore:50,afterScore:75,aiPowered:false});}catch(e){res.json({ok:false,error:e.message});}});
app.get('/api/ai/best-time',authRequired,async(req,res)=>{try{const uid=req.session.user.id;const snap=await db.collection('users').doc(uid).collection('emailLog').orderBy('sentAt','desc').limit(100).get();const hs={};snap.forEach(d=>{const data=d.data();const ms=toMs(data.sentAt);const h=new Date(ms).getHours();if(!hs[h])hs[h]={sent:0};hs[h].sent++;});try{const hist=Object.entries(hs).map(function(kv){return 'Hour '+kv[0]+': sent='+kv[1].sent;}).join('\n');const prompt='Recommend 3 best hours for B2B emails. JSON only.\n'+(hist||'No data')+'\nReturn: {"bestHours":[h1,h2,h3],"reasoning":"short"}';const text=await callAI(prompt,uid);const parsed=safeParseJSON(text);if(parsed&&parsed.bestHours)return res.json(Object.assign({ok:true,aiPowered:true},parsed));}catch(e){}res.json({ok:true,bestHours:[9,11,14],reasoning:'Default',aiPowered:false});}catch(e){res.json({ok:true,bestHours:[9,11,14],reasoning:'Default',aiPowered:false});}});
