app.get('/api/recipients',authRequired,async(req,res)=>{try{const uid=req.session.user.id;const page=Math.max(1,parseInt(req.query.page)||1);const limit=Math.min(200,parseInt(req.query.limit)||10);const search=String(req.query.search||'').toLowerCase().trim();const statusFilter=String(req.query.status||'all');const ck='recipients:'+uid+':'+page+':'+limit+':'+search+':'+statusFilter;const cached=cacheGet(ck);if(cached)return res.json(cached);const colRef=db.collection('users').doc(uid).collection('recipients');const allSnap=await colRef.limit(2000).get();let all=[];const backfill=db.batch();let bfCount=0;allSnap.forEach(d=>{const data=d.data();const rec=Object.assign({id:d.id},data);let sc=parseInt(data.sendCount,10)||0;const st=(data.status||'').toLowerCase();if(sc===0&&(st==='sent'||st==='opened'||st==='delivered'||st.indexOf('opened')!==-1)){sc=1;rec.sendCount=1;}else{rec.sendCount=sc;}all.push(rec);if(!data.bumpAt||data.sendCount===undefined){const u={};if(!data.bumpAt)u.bumpAt=data.createdAt||new Date();if(data.sendCount===undefined)u.sendCount=sc;backfill.set(d.ref,u,{merge:true});bfCount++;}});if(bfCount>0)backfill.commit().catch(function(){});all.sort((a,b)=>toMs(b.bumpAt||b.lastSentAt||b.sentAt||b.createdAt)-toMs(a.bumpAt||a.lastSentAt||a.sentAt||a.createdAt));if(statusFilter!=='all'){const want=statusFilter.toLowerCase();all=all.filter(r=>{const s=(r.status||'').toLowerCase();if(want==='pending')return s==='pending';if(want==='sent')return s==='sent';if(want==='opened')return s==='opened';if(want==='scheduled')return s==='scheduled';if(want==='saved')return s==='saved';return s===want;});}if(search)all=all.filter(r=>(r.email||'').toLowerCase().indexOf(search)!==-1||(r.company||'').toLowerCase().indexOf(search)!==-1);const total=all.length;const totalPages=Math.max(1,Math.ceil(total/limit));const safePage=Math.min(page,totalPages);const offset=(safePage-1)*limit;const sliced=all.slice(offset,offset+limit);let sendsAllTime=0,pendingCount=0,scheduledCount=0,sentCount2=0,openedCount=0,savedCount=0;for(let ri=0;ri<all.length;ri++){const rr=all[ri];const sc=parseInt(rr.sendCount,10)||0;sendsAllTime+=sc;const stx=(rr.status||'').toLowerCase();if(stx==='pending')pendingCount++;else if(stx==='scheduled')scheduledCount++;else if(stx==='opened'||stx.indexOf('opened')!==-1)openedCount++;else if(stx==='sent')sentCount2++;else if(stx==='saved')savedCount++;}const summary={recipientsTotal:total,mailflowSendsAllTime:sendsAllTime,pending:pendingCount,scheduled:scheduledCount,sent:sentCount2,opened:openedCount,saved:savedCount};const out={ok:true,recipients:sliced,summary:summary,pagination:{page:safePage,limit,total,totalPages,hasMore:safePage<totalPages}};cacheSet(ck,out,CACHE_TTL.recipients);res.json(out);}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/recipients',authRequired,async(req,res)=>{try{const{list,templateId,saveOnly}=req.body;if(!list||!list.length)return res.json({ok:false,error:'No recipients provided'});const uid=req.session.user.id;const batch=db.batch();const ref=db.collection('users').doc(uid).collection('recipients');const created=[];const now=new Date();const initialStatus=saveOnly===true?'Saved':'Pending';for(const r of list){if(!r.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email))continue;const doc=ref.doc();const rec={company:(r.company||'').trim(),email:r.email.toLowerCase(),templateId:templateId||'',status:initialStatus,sentAt:null,openedAt:null,everOpened:false,createdAt:now,bumpAt:now,sendCount:0};batch.set(doc,rec);created.push({id:doc.id,company:rec.company,email:rec.email,templateId:rec.templateId,status:initialStatus,sentAt:null,openedAt:null,everOpened:false,createdAt:now.toISOString(),bumpAt:now.toISOString(),sendCount:0});}await batch.commit();cacheDel('recipients:'+uid);cacheDel('stats:'+uid);res.json({ok:true,added:created.length,recipients:created,status:initialStatus});}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/recipients/save-and-send',authRequired,rateLimit(60*1000,20,null),async(req,res)=>{try{const uid=req.session.user.id;const ue=req.session.user.email;const{list,templateId,includeSignature,includeLogo,includeAttachments,selectedFileIds}=req.body||{};if(!Array.isArray(list)||!list.length)return res.json({ok:false,error:'No recipients'});if(!templateId)return res.json({ok:false,error:'Template required'});const u=await getUserData(uid);if(!u||!u.smtpEnabled)return res.json({ok:false,error:'Connect Gmail first to send'});const today=new Date().toISOString().split('T')[0];const sdChk=await db.collection('users').doc(uid).collection('stats').doc(today).get();const sentToday=sdChk.exists?(sdChk.data().sent||0):0;const limit=u.dailyLimit||DEFAULT_DAILY_LIMIT;if(sentToday>=limit)return res.json({ok:false,error:'DAILY_LIMIT_REACHED',sent:sentToday,limit});const ref=db.collection('users').doc(uid).collection('recipients');const batch=db.batch();const created=[];const now=new Date();for(const r of list){if(!r.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email))continue;const doc=ref.doc();const rec={company:(r.company||'').trim(),email:r.email.toLowerCase(),templateId:templateId||'',status:'Pending',sentAt:null,openedAt:null,everOpened:false,createdAt:now,bumpAt:now,sendCount:0};batch.set(doc,rec);created.push({id:doc.id,email:rec.email,company:rec.company});}await batch.commit();cacheDel('recipients:'+uid);cacheDel('stats:'+uid);let sent=0,failed=0,dupSkipped=0;const sentDetails=[];const errors=[];for(let i=0;i<created.length;i++){const rec=created[i];try{const result=await sendOne(uid,ue,rec.id,{force:true,skipDelay:true,forceResend:true,isManualSend:true,includeSignature:includeSignature!==false,includeLogo:includeLogo!==false,includeAttachments:includeAttachments===true,selectedFileIds:Array.isArray(selectedFileIds)?selectedFileIds:[],templateId:templateId});sent++;sentDetails.push({id:rec.id,email:result.email,attachmentsCount:result.attachmentsCount});if(i<created.length-1)await sleep(600);}catch(err){if(err.code==='DAILY_LIMIT_REACHED'){errors.push({id:rec.id,error:'Daily limit reached'});break;}if(err.code==='DUPLICATE_SEND_SKIP'){dupSkipped++;continue;}failed++;errors.push({id:rec.id,error:err.message});}}res.json({ok:true,added:created.length,recipients:created,sent,failed,duplicatesSkipped:dupSkipped,sentDetails,errors:errors.slice(0,10)});}catch(e){res.json({ok:false,error:e.message});}});
