app.get('/api/quota',authRequired,async(req,res)=>{try{const userId=req.session.user.id;const force=req.query.force==='1';const ck='quota:'+userId;if(!force){const cached=cacheGet(ck);if(cached)return res.json(cached);}const u=await getUserData(userId);if(!u||!u.smtpEnabled)return res.json({ok:false,error:'Gmail not connected',noTokens:true});const today=new Date().toISOString().split('T')[0];const sdChk=await db.collection('users').doc(userId).collection('stats').doc(today).get();const mailflowSentToday=sdChk.exists?(sdChk.data().sent||0):0;const limit=u.dailyLimit||DEFAULT_DAILY_LIMIT;let gmailSentToday=null;let gmailSource='unavailable';let imapAvailable=false;let gmailError=null;let syncMs=0;if(u.imapEnabled&&u.imapAppPassword){imapAvailable=true;const imapKey='gmailSent:'+userId;let g=null;if(force){const t0=Date.now();g=await fetchGmailSentTodayCount(u.email,u.imapAppPassword).catch(function(err){return{ok:false,error:err.message};});syncMs=Date.now()-t0;}else{g=cacheGet(imapKey);if(!g){const t0=Date.now();g=await fetchGmailSentTodayCount(u.email,u.imapAppPassword).catch(function(err){return{ok:false,error:err.message};});syncMs=Date.now()-t0;}}if(g&&g.ok){gmailSentToday=g.count;gmailSource=g.method||'imap_sent_folder';cacheSet(imapKey,g,60e3);}else if(g&&g.error){gmailError=g.error;}}const totalSentToday=(gmailSentToday!==null&&gmailSentToday!==undefined)?Math.max(mailflowSentToday,gmailSentToday):mailflowSentToday;const remaining=Math.max(0,limit-totalSentToday);let allTime=null;if(req.query.all==='1'){try{const mfAll=await db.collection('users').doc(userId).collection('emailLog').count().get();const mfAllN=mfAll.data().count||0;let gmAll=null,gmAllErr=null;if(u.imapEnabled&&u.imapAppPassword){const cachedAll=cacheGet('gmailTotal:'+userId);if(cachedAll){gmAll=cachedAll;}else{const gt=await fetchGmailSentTotal(u.email,u.imapAppPassword).catch(function(err){return{ok:false,error:err.message};});if(gt&&gt.ok){gmAll=gt.total;cacheSet('gmailTotal:'+userId,gt.total,300e3);}else if(gt&&gt.error){gmAllErr=gt.error;}}}const effectiveGmail=(gmAll!==null&&gmAll!==undefined)?Math.max(gmAll,mfAllN):mfAllN;allTime={mailflowSent:mfAllN,gmailSent:gmAll,gmailError:gmAllErr,total:effectiveGmail};}catch(e){allTime={error:e.message};}}const out={ok:true,sent:totalSentToday,mailflowSent:mailflowSentToday,gmailSent:gmailSentToday,gmailSource:gmailSource,gmailError:gmailError,imapAvailable:imapAvailable,limit:limit,gmailDailyMax:GMAIL_DAILY_MAX,remaining:remaining,allTime:allTime,usedPercent:limit>0?Math.min(100,Math.round((totalSentToday/limit)*100)):0,lastSyncAt:new Date().toISOString(),syncMs:syncMs,timestamp:new Date().toISOString(),live:(gmailSentToday!==null&&gmailSentToday!==undefined),cached:false};cacheSet(ck,out,60e3);res.json(out);}catch(e){res.json({ok:false,error:e.message});}});
