app.get('/api/admin/user/:id/details',adminRequired,async(req,res)=>{try{const uid=req.params.id;const d=await db.collection('users').doc(uid).get();if(!d.exists)return res.json({ok:false,error:'Not found'});const data=d.data();const banned=await db.collection('bannedUsers').doc(uid).get();const today=new Date().toISOString().split('T')[0];const month=today.substring(0,7);const[t,s,p,sd,aiT,aiM,aiAll,ocrT,ocrAll,o]=await Promise.all([db.collection('users').doc(uid).collection('recipients').count().get(),db.collection('users').doc(uid).collection('recipients').where('status','in',['Sent','Opened']).count().get(),db.collection('users').doc(uid).collection('recipients').where('status','==','Pending').count().get(),db.collection('users').doc(uid).collection('emailLog').count().get(),db.collection('users').doc(uid).collection('aiUsage').doc(today).get(),db.collection('users').doc(uid).collection('aiUsage').doc('month_'+month).get(),db.collection('users').doc(uid).collection('aiUsage').doc('total').get(),db.collection('users').doc(uid).collection('ocrUsage').doc(today).get(),db.collection('users').doc(uid).collection('ocrUsage').doc('total').get(),db.collection('users').doc(uid).collection('recipients').where('status','==','Opened').count().get()]);const aiUsage={today:aiT.exists?(aiT.data().totalTokens||0):0,todayCalls:aiT.exists?(aiT.data().calls||0):0,month:aiM.exists?(aiM.data().totalTokens||0):0,monthCalls:aiM.exists?(aiM.data().calls||0):0,total:aiAll.exists?(aiAll.data().totalTokens||0):0,calls:aiAll.exists?(aiAll.data().calls||0):0,providers:aiAll.exists?(aiAll.data().providers||{}):{}};const ocrClientErrsT=ocrT.exists?(ocrT.data().clientErrors||0):0;const ocrClientErrsAll=ocrAll.exists?(ocrAll.data().clientErrors||0):0;const ocrUsage={todayTotal:(ocrT.exists?(ocrT.data().total||0):0)+ocrClientErrsT,todaySuccess:ocrT.exists?(ocrT.data().success||0):0,todayFailed:(ocrT.exists?(ocrT.data().failed||0):0)+ocrClientErrsT,todayClientErrors:ocrClientErrsT,totalTotal:(ocrAll.exists?(ocrAll.data().total||0):0)+ocrClientErrsAll,totalSuccess:ocrAll.exists?(ocrAll.data().success||0):0,totalFailed:(ocrAll.exists?(ocrAll.data().failed||0):0)+ocrClientErrsAll,totalClientErrors:ocrClientErrsAll,totalChars:ocrAll.exists?(ocrAll.data().charsExtracted||0):0};res.json({ok:true,user:{id:uid,email:data.email,name:data.name,picture:data.profilePicture||'',appAccountId:data.appAccountId||'N/A',createdAt:data.createdAt?(data.createdAt.toDate?data.createdAt.toDate().toISOString():data.createdAt):null,lastLogin:data.lastLogin?(data.lastLogin.toDate?data.lastLogin.toDate().toISOString():data.lastLogin):null,authType:data.authType||'email',hasSmtp:!!data.smtpEnabled,hasImap:!!data.imapEnabled,autoSend:!!data.autoSend,banned:banned.exists,banReason:banned.exists?banned.data().reason:'',deleted:data.deleted===true,deletedAt:data.deletedAt||null,aiUsage,ocrUsage,stats:{total:t.data().count,sent:s.data().count,opened:o.data().count,pending:p.data().count,totalSends:sd.data().count}}});}catch(e){res.json({ok:false,error:e.message});}});
app.delete('/api/admin/user/:id',adminRequired,async(req,res)=>{try{const uid=req.params.id;if(!uid)return res.json({ok:false,error:'Missing user ID'});const target=await db.collection('users').doc(uid).get();if(!target.exists)return res.json({ok:false,error:'User not found'});const data=target.data();const email=(data.email||'').toLowerCase();if(email===ADMIN_EMAIL)return res.json({ok:false,error:'Cannot delete admin account'});const SUBCOLLECTIONS=['recipients','templates','emailLog','files','stats','senderMemory','imapEmails','aiUsage','replyLog','ocrUsage','ocrLog','aiErrors','sendLocks','scheduledBatches','sentStripLog'];const snapshot={user:data,createdAt:new Date(),deletedBy:req.session.user.email,subcollections:{}};for(const coll of SUBCOLLECTIONS){const items=[];let more=true;while(more){const snap=await db.collection('users').doc(uid).collection(coll).limit(400).get();if(snap.empty){more=false;break;}snap.forEach(d=>items.push({id:d.id,data:d.data()}));if(snap.size<400)more=false;}snapshot.subcollections[coll]=items;}await db.collection('deletedUsers').doc(uid).set(snapshot);await db.collection('users').doc(uid).update({deleted:true,deletedAt:new Date(),deletedBy:req.session.user.email,email_original:data.email,email:data.email+'.deleted.'+Date.now()});await db.collection('bannedUsers').doc(uid).delete().catch(function(){});res.json({ok:true,deleted:true,recoverable:true,email:data.email,snapshotAt:new Date().toISOString()});}catch(e){res.json({ok:false,error:e.message});}});
app.get('/api/admin/deleted-users',adminRequired,async(req,res)=>{try{const snap=await db.collection('deletedUsers').orderBy('createdAt','desc').limit(200).get();const list=[];snap.forEach(d=>{const dd=d.data();list.push({id:d.id,email:(dd.user&&dd.user.email)||'—',name:(dd.user&&dd.user.name)||'',appAccountId:(dd.user&&dd.user.appAccountId)||'',createdAt:dd.createdAt,deletedBy:dd.deletedBy,recipientsCount:((dd.subcollections&&dd.subcollections.recipients&&dd.subcollections.recipients.length)||0),emailLogCount:((dd.subcollections&&dd.subcollections.emailLog&&dd.subcollections.emailLog.length)||0)});});res.json({ok:true,users:list});}catch(e){res.json({ok:false,error:e.message});}});
app.post('/api/admin/deleted-users/:id/recover',adminRequired,async(req,res)=>{try{const uid=req.params.id;const snap=await db.collection('deletedUsers').doc(uid).get();if(!snap.exists)return res.json({ok:false,error:'Snapshot not found'});const s=snap.data();const userData=s.user||{};const originalEmail=userData.email_original||userData.email;const restoredUser=Object.assign({},userData);delete restoredUser.deleted;delete restoredUser.deletedAt;delete restoredUser.deletedBy;delete restoredUser.email_original;restoredUser.email=originalEmail;restoredUser.restoredAt=new Date();restoredUser.restoredBy=req.session.user.email;await db.collection('users').doc(uid).set(restoredUser,{merge:true});const subs=s.subcollections||{};for(const coll of Object.keys(subs)){const items=subs[coll]||[];for(let i=0;i<items.length;i+=400){const chunk=items.slice(i,i+400);const b=db.batch();for(const it of chunk){b.set(db.collection('users').doc(uid).collection(coll).doc(it.id),it.data,{merge:true});}await b.commit();}}await db.collection('deletedUsers').doc(uid).delete().catch(function(){});res.json({ok:true,recovered:true,email:originalEmail,restoredSubcollections:Object.keys(subs)});}catch(e){res.json({ok:false,error:e.message});}});
app.use((err,req,res,next)=>{console.error('Unhandled:',err.message);if(res.headersSent)return next(err);res.status(500).json({ok:false,error:'Internal server error'});});
app.use((req,res,next)=>{if(req.method==='GET'&&req.path.indexOf('/api')!==0&&req.path.indexOf('/auth')!==0&&req.path.indexOf('/track')!==0&&req.path.indexOf('/click')!==0&&req.path.indexOf('/logo')!==0){return res.sendFile(path.join(__dirname,'public','index.html'));}next();});
if(process.env.VERCEL){module.exports=app;}else{app.listen(PORT,function(){console.log('MailFlow Pro v'+APP_VERSION+' running on port '+PORT);});}